"""Generate linked experiment proposals after the variable inventory exists."""
import json
from pathlib import Path
from integrate_third_question_pass import write,dump,table
ROOT=Path(__file__).resolve().parents[1];MET=ROOT/'research_questions/operationalization'
def main():
    if (MET/'experiments.json').exists():raise SystemExit('Already authored; preserve earlier proposal.')
    vs=json.loads((MET/'variables.json').read_text());byname={v['name']:v for v in vs}
    g=json.loads((ROOT/'research_questions/question_graph.json').read_text());qs={q['id']:q for q in g['nodes']}
    proposals=[
    ('RQ-03.03',['T','cp','ω','Force / Forces'],'Définir et étalonner une indication indépendante de Force, puis comparer T intégré à la loi quadratique hors calibration.','T∝ω² à cp fixe','Exposant non quadratique ou cp variable','NEEDS_DEFINITION','NOT_TESTABLE','Élevé; instrument économique absent','DESIGNED_NOT_EXECUTED'),
    ('RQ-05.03',['Utility','price'],'Comparer classements et ratios sous transformations croissantes; données synthétiques uniquement.','Classement insuffisant pour rapport Utility','Échelle cardinale indépendante pourrait lever indétermination','DO_NOW','MEDIUM','Faible; diagnostic formel','EXECUTED_FORMAL'),
    ('RQ-08.02',['K','T','Money'],'Deux et trois produits; réplication de composition fixe puis poids variables.','K invariant sous réplication proportionnelle, pas sous recomposition générale','Homogénéité des Ki stabilise K même avec composition variable','DO_NOW','MEDIUM','Faible; formal_results.json','EXECUTED_FORMAL'),
    ('RQ-04.04',['η','Utility'],'Calcul conditionnel à π/8 puis examen de dérivée libre, sans confondre optimum contraint et libre.','Valeur .3431 conditionnelle; contrainte supplémentaire nécessaire','Autre domaine admissible sélectionne autre valeur','DO_NOW','MEDIUM','Faible; formal_results.json','EXECUTED_FORMAL'),
    ('RQ-09.02',['energy','useful work','ω'],'Procédé homogène à plusieurs vitesses; compteur, couple, durée et déchets, qualité fixée.','Tester la proposition physique de pertes p165 séparément de T','Pertes linéaires, fixes ou rendement croissant selon procédé','NEEDS_DATA','MEDIUM','Modéré; laboratoire ou usine; domaine à pré-spécifier','DESIGNED_NOT_EXECUTED'),
    ('RQ-05.01',['cost','price','profit','productivity','Utility','consumer gain'],'Panel produit-usine-client; coûts complets, factures, caractéristiques, quantités et énergie avant/après procédé.','Branches de partage conditionnelles, pas transmission automatique','Concurrence, markups, demande et autres intrants','NEEDS_DATA','LOW','Élevé; données commerciales appariées','DESIGNED_NOT_EXECUTED'),
    ('RQ-10.02',['consumer gain','price','standard of living','environmental damage'],'Panel ménages avec exposition exogène à baisse de prix; dépenses, actifs, dettes, transferts; empreintes séparées.','Usage variable entre consommation, épargne et autres destinations','Effets revenu/substitution standards et chocs de revenu simultanés','NEEDS_DATA','LOW','Élevé; contrefactuel et données de panel','DESIGNED_NOT_EXECUTED'),
    ('RQ-12.02',['K','energy'],'Pré-spécifier K=GDP/E sur période de calibration et prévoir période tenue à l’écart; proxies seulement.','Couplage stable sous conditions constantes','Intensité énergétique évolutive et changement de composition','DO_LATER','LOW','Faible; données indépendantes déjà archivées; pas de régression cette passe','DESIGNED_NOT_EXECUTED')]
    experiments=[]
    for i,(qid,names,design,pred,alt,feas,power,cost,execution) in enumerate(proposals,1):
        experiments.append(dict(id=f'EXP-{i:02}',question=qid,claims=qs[qid]['claims'],variables=[dict(id=byname[n]['id'],name=n,measurement_level=byname[n]['measurement_level']) for n in names],data='Synthetic only' if execution=='EXECUTED_FORMAL' else cost,design=design,prediction=pred,alternative_prediction=alt,discriminating_power=power,cost_complexity=cost,feasibility=feas,execution_status=execution,measurement_scope='Formal diagnostics do not claim empirical observation of L0/L1 variables',independent_law_test=False))
    dump('research_questions/operationalization/experiments.json',experiments)
    write('research_questions/operationalization/experiments.md','# Expériences proposées\n\nAucune nouvelle régression. DO_NOW désigne ici des diagnostics synthétiques exécutés, non des mesures de T.\n\n'+table(['ID','Question','Design','Prédiction','Alternative','Pouvoir','Faisabilité','Exécution'],[(e['id'],e['question'],e['design'],e['prediction'],e['alternative_prediction'],e['discriminating_power'],e['feasibility'],e['execution_status']) for e in experiments]))
    write('research_questions/RQ-08.02/K_operationalization.md','# K : usages et estimabilité\n\nSOURCE: PDF559, coefficient variable par Product, puis stabilité alléguée avec grand nombre de Products. PDF202 distingue cp et ca.\n\nINTERPRETATION:\n\n'+table(['Usage','Classe','Conditions'],[
    ['K local M/T','K_CALIBRATABLE conditionnel','M et T indépendants, unités et transformation fixées; pas actuellement disponibles'],
    ['K macro GDP/E par date','K_ESTIMABLE; K_RESIDUAL','Proxies indépendants disponibles; ratio n’établit pas coefficient structurel'],
    ['K tenu fixe pour prévision','K_CALIBRATABLE','Période de calibration distincte, composition et technologie surveillées'],
    ['K commun uniquement lié aux unités','K_STRUCTURAL hypothétique','Stabilité de composition, pondérations, pertes et coefficients à justifier'],
    ['K sans frontière ni dénominateur indépendant','K_UNDEFINED opérationnellement','Définir mesurande et protocole avant estimation']])+ '\nDiagnostic synthétique: [résultats](../operationalization/formal_results.json). La réplication de mêmes produits stabilise K sans le rendre universel. Deux et trois produits changent K sous recomposition. Pas de nouvelle preuve empirique; hypothèses d’additivité conservées.\n')
    write('research_questions/operationalization/README.md','# Métrologie du programme Campergue\n\n[Variables](variables.md) · [Matrice](measurement_matrix.csv) · [Circularité](circularity_review.md) · [Expériences](experiments.md) · [Littérature](literature.md) · [Rapport](../third_pass_report.md).\n\nLes dossiers existants ne sont pas remplacés. Les versions antérieures des fichiers modifiés sont conservées sous ../history/third_pass_before. Définitions du manuscrit, interprétations, proxies et résultats synthétiques restent séparés. Les niveaux concernent les grandeurs cibles; une série de prix répétée ne transforme pas Utility en mesure indépendante.\n')
if __name__=='__main__':main()
